arguments.script:
var prefix=GameMenuUI.PreferencePrefix;var prior=CampaignLevel.Current;
var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var checks=new System.Collections.Generic.List<string>();
UnityEngine.SceneManagement.Scene test=default;
UnityEngine.GameObject go=null;
var audioField=typeof(GameplayAudio).GetField("instance",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);var oldAudio=audioField.GetValue(null);UnityEngine.GameObject silentGo=null;
void Check(bool ok,string label){if(!ok)throw new System.Exception(label);checks.Add(label);}
try {
GameMenuUI.PreferencePrefix="Goombas.Tests.CoinLives."+System.Guid.NewGuid()+".";
test=UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Additive);
go=new UnityEngine.GameObject("Coin lives isolated test");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,test);
silentGo=new UnityEngine.GameObject("Isolated silent audio");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(silentGo,test);var silent=silentGo.AddComponent<GameplayAudio>();silent.enabled=false;audioField.SetValue(null,silent);var last=(System.Collections.Generic.Dictionary<string,float>)typeof(GameplayAudio).GetField("last",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(silent);last["coin"]=float.MaxValue;
var level=go.AddComponent<CampaignLevel>();level.enabled=false;
var awake=typeof(CampaignLevel).GetMethod("Awake",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);awake.Invoke(level,null);
Check(level.Lives==3,"initial lives 3");Check(level.CoinCount==0,"initial coins 0");
Check(level.CollectCoin(4),"coin collected");Check(level.CoinCount==1,"HUD source increments immediately");Check(!level.CollectCoin(4)&&level.CoinCount==1,"duplicate suppressed");
Check(level.CollectLegacyCoin()&&level.CoinCount==2,"legacy coin shares HUD source");
var purse=go.AddComponent<Winning.CoinPurse>();purse.Increment();Check(purse.Count==3&&level.CoinCount==3,"wallet increment persists");
level.LoseLife();Check(level.Lives==2&&level.CoinCount==3,"first death retains coins");
UnityEngine.Object.DestroyImmediate(go);
go=new UnityEngine.GameObject("Recreated after first death");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,test);level=go.AddComponent<CampaignLevel>();level.enabled=false;awake.Invoke(level,null);purse=go.AddComponent<Winning.CoinPurse>();
Check(level.Lives==2&&level.CoinCount==3&&purse.Count==3,"new objects after first death retain wallet and lives");
level.LoseLife();Check(level.Lives==1&&level.CoinCount==3,"second death retains coins");
UnityEngine.Object.DestroyImmediate(go);go=new UnityEngine.GameObject("Recreated after second death");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,test);level=go.AddComponent<CampaignLevel>();level.enabled=false;awake.Invoke(level,null);purse=go.AddComponent<Winning.CoinPurse>();Check(level.Lives==1&&purse.Count==3,"second object recreation retains coins");
level.LoseLife();Check(level.Lives==0&&level.CoinCount==0,"third death clears coins");
Check(!level.CollectCoin(5),"dead run cannot collect");level.LoseLife();Check(level.Lives==0,"lives never negative");
awake.Invoke(level,null);Check(level.Lives==3&&level.CoinCount==0,"respawn restores three lives with zero coins");
Check(level.CollectCoin(4),"cleared coin recollectable");
Check(CampaignLevel.CoinStars(9)==0&&CampaignLevel.CoinStars(10)==1&&CampaignLevel.CoinStars(24)==2&&CampaignLevel.CoinStars(40)==3,"star thresholds");
return new {passed=checks.Count,checks};
} finally {
if(go!=null)UnityEngine.Object.DestroyImmediate(go);
if(silentGo!=null)UnityEngine.Object.DestroyImmediate(silentGo);audioField.SetValue(null,oldAudio);
if(test.IsValid())UnityEditor.SceneManagement.EditorSceneManager.CloseScene(test,true);
if(original.IsValid())UnityEngine.SceneManagement.SceneManager.SetActiveScene(original);
GameMenuUI.PreferencePrefix=prefix;
typeof(CampaignLevel).GetProperty("Current").SetValue(null,prior);
}
